// Class 10 PSEB Social Science practice bank, part 4.
StudyData.addPractice(10, "sstpb", {
  "anglo-sikh-wars": {
    mcq: [
      { q: "The First Anglo-Sikh War was fought in:", options: ["1839–40", "1845–46", "1848–49", "1857–58"], answer: 1, explain: "The First Anglo-Sikh War lasted from 1845 to 1846.", level: 1 },
      { q: "Who became the child Maharaja of Punjab with his mother Rani Jindan as regent?", options: ["Kharak Singh", "Sher Singh", "Nau Nihal Singh", "Duleep Singh"], answer: 3, explain: "Duleep Singh was made Maharaja while still a child, with Rani Jindan as regent.", level: 1 },
      { q: "The decisive battle of the First Anglo-Sikh War was fought at:", options: ["Mudki", "Sobraon", "Aliwal", "Gujrat"], answer: 1, explain: "At Sobraon on 10 February 1846 the Sikh army was defeated.", level: 1 },
      { q: "The revolt at Multan in 1848 was led by:", options: ["Chattar Singh Attariwala", "Dewan Mulraj", "Lal Singh", "Tej Singh"], answer: 1, explain: "Dewan Mulraj's revolt began the Second Anglo-Sikh War.", level: 1 },
      { q: "The final battle of the Second Anglo-Sikh War was fought at:", options: ["Chillianwala", "Ramnagar", "Gujrat", "Ferozeshah"], answer: 2, explain: "The Sikh army was finally defeated at Gujrat on 21 February 1849.", level: 1 },
      { q: "Punjab was annexed to British India on 29 March 1849 by:", options: ["Lord Dalhousie", "Lord Hardinge", "Lord Dufferin", "Lord Curzon"], answer: 0, explain: "Lord Dalhousie, the Governor-General, annexed Punjab.", level: 1 },
      { q: "By the Treaty of Lahore (March 1846), the Sikhs had to hand over to the British:", options: ["Multan", "Kashmir only", "Peshawar", "the Jalandhar Doab"], answer: 3, explain: "The Jalandhar Doab was handed over, a war indemnity was demanded and the army was limited.", level: 2 },
      { q: "A British Resident was posted at Lahore under the Treaty of Lahore to:", options: ["collect taxes personally", "guide and supervise the government", "command the Sikh army", "rule as Maharaja"], answer: 1, explain: "A Resident is a British officer who supervises an Indian state's government.", level: 2 },
      { q: "Kashmir was given to Gulab Singh of Jammu under the:", options: ["Treaty of Amritsar (1846)", "Treaty of Lahore (1809)", "Treaty of Bhairowal (1849)", "Treaty of Sobraon (1850)"], answer: 0, explain: "Gulab Singh received Kashmir under the Treaty of Amritsar of 1846.", level: 2 },
      { q: "Rani Jindan lost her power and a British-controlled council ran the government after the:", options: ["Treaty of Amritsar (1809)", "Treaty of Bhairowal (December 1846)", "Battle of Mudki", "Annexation of 1849"], answer: 1, explain: "By the Treaty of Bhairowal, a council under British control took over.", level: 2 },
      { q: "Why did the Sikh court leaders Lal Singh and Tej Singh face blame?", options: ["They put their own interests before the kingdom", "They deserted to Nepal", "They joined the Mughals", "They refused to fight"], answer: 0, explain: "They were accused of placing personal interests above the Sikh state during the wars.", level: 2 },
      { q: "In the Second Anglo-Sikh War, which of these battles took place in 1848–49?", options: ["Mudki", "Aliwal", "Sobraon", "Chillianwala"], answer: 3, explain: "Chillianwala (January 1849) belongs to the second war; Mudki, Aliwal and Sobraon were in the first.", level: 2 },
      { q: "Assertion (A): After Ranjit Singh's death, the Khalsa army became very influential in politics.\nReason (R): Weak successors and quarrels in the court left a power gap.", options: ["Both A and R are true, and R is the correct explanation of A.", "Both A and R are true, but R is not the correct explanation of A.", "A is true, but R is false.", "A is false, but R is true."], answer: 0, explain: "The weakness of the court allowed the army panchayats to gain influence.", level: 2, keepOrder: true },
      { q: "Assertion (A): The Koh-i-Noor was taken to England after the annexation.\nReason (R): Duleep Singh was pensioned off and sent away from Punjab.", options: ["Both A and R are true, and R is the correct explanation of A.", "Both A and R are true, but R is not the correct explanation of A.", "A is true, but R is false.", "A is false, but R is true."], answer: 1, explain: "Both happened after annexation, but the pension does not explain the removal of the diamond.", level: 3, keepOrder: true },
      { q: "Which sequence lists the battles of the First Anglo-Sikh War in the correct order?", options: ["Aliwal, Mudki, Sobraon, Ferozeshah", "Mudki, Ferozeshah, Aliwal, Sobraon", "Sobraon, Aliwal, Ferozeshah, Mudki", "Ferozeshah, Mudki, Sobraon, Aliwal"], answer: 1, explain: "Mudki and Ferozeshah in December 1845, Aliwal in January 1846, Sobraon in February 1846.", level: 3 },
      { q: "Sham Singh Attariwala is remembered for:", options: ["signing the Treaty of Lahore", "dying while commanding the Sikh army at Sobraon", "leading the Multan revolt", "surrendering at Gujrat"], answer: 1, explain: "He died fighting bravely at Sobraon.", level: 3 },
      { q: "Which of the following is NOT a cause of the fall of the Sikh kingdom?", options: ["Weak successors", "Conflict in the court", "Unity of all Sikh leaders", "British desire for the north-west frontier"], answer: 2, explain: "Lack of unity, not unity, caused the fall.", level: 3 },
      { q: "After annexation in 1849 the new British administration of Punjab was headed initially by:", options: ["Duleep Singh", "Rani Jindan", "A Board of Administration under Henry Lawrence", "Gulab Singh"], answer: 2, explain: "Punjab was divided into districts under a Board of Administration headed by Henry Lawrence.", level: 3 }
    ],
    written: [
      { q: "When was Punjab annexed to British India?", a: "On 29 March 1849, by Lord Dalhousie.", marks: 1 },
      { q: "Who was the regent of Maharaja Duleep Singh?", a: "His mother, Rani Jindan.", marks: 1 },
      { q: "Name the battles of the First Anglo-Sikh War.", a: "Mudki, Ferozeshah, Aliwal and Sobraon.", marks: 1 },
      { q: "What is meant by 'war indemnity'?", a: "It is a payment demanded from the defeated side to cover the costs of war.\nIn 1846 the British demanded a large indemnity from the Sikhs.", marks: 2 },
      { q: "State two terms of the Treaty of Lahore (1846).", a: "The Jalandhar Doab was handed over to the British and a large war indemnity was demanded.\nThe Sikh army was limited and a British Resident was posted at Lahore.", marks: 2 },
      { q: "What was the fate of Maharaja Duleep Singh after annexation?", a: "He was pensioned off and sent away from Punjab.\nThe Koh-i-Noor diamond was taken to England.", marks: 2 },
      { q: "Describe the political condition of Punjab after the death of Ranjit Singh.", a: "1. A struggle for power followed among Kharak Singh, Nau Nihal Singh and Sher Singh.\n2. The child Duleep Singh was made Maharaja with Rani Jindan as regent.\n3. The Khalsa army gained influence while court leaders put their own interests first.", marks: 3 },
      { q: "Why did the Second Anglo-Sikh War begin?", a: "1. Dewan Mulraj revolted at Multan in 1848 after two British officers were killed there.\n2. The revolt spread, and Sikh chiefs like Chattar Singh and Sher Singh Attariwala joined.\n3. The British used it as a reason to fight and then annexed Punjab.", marks: 3 },
      { q: "Explain three causes of the fall of the Sikh kingdom.", a: "1. Weak successors after Ranjit Singh.\n2. Conflicts in the court and the disloyalty of some leaders.\n3. The British desire for the north-west frontier and their superior forces and resources.", marks: 3 },
      { q: "Describe the First Anglo-Sikh War and its results.", a: "1. The Sikh army crossed the Sutlej in December 1845 and the British declared war.\n2. Battles were fought at Mudki, Ferozeshah, Aliwal and Sobraon.\n3. The Sikhs were defeated at Sobraon on 10 February 1846.\n4. By the Treaty of Lahore the Jalandhar Doab was lost, an indemnity demanded, the army limited and a Resident posted.\n5. Kashmir went to Gulab Singh and, by the Treaty of Bhairowal, Rani Jindan lost power.", marks: 5, type: "long" },
      { q: "Describe the Second Anglo-Sikh War and the annexation of Punjab.", a: "1. It began with Mulraj's revolt at Multan in 1848.\n2. Battles were fought at Ramnagar and Chillianwala (1849).\n3. Multan surrendered in January 1849.\n4. The Sikhs were finally defeated at Gujrat on 21 February 1849.\n5. On 29 March 1849 Dalhousie annexed Punjab; Duleep Singh was pensioned and Henry Lawrence headed the Board of Administration.", marks: 5, type: "long" },
      { q: "Case study: In 1846, after losing a battle on the Sutlej, the Sikh government signed a treaty with the British. A British officer was posted at Lahore to oversee the government, the Sikh army was reduced and a large sum was demanded.\n(i) Name the treaty. (ii) Who was the British officer called? (iii) What was the sum demanded called?", a: "(i) Treaty of Lahore (March 1846).\n(ii) The British Resident.\n(iii) A war indemnity.", marks: 4, type: "case" }
    ]
  },
  "punjab-freedom-struggle": {
    mcq: [
      { q: "The Namdhari (Kuka) movement was started by:", options: ["Baba Ram Singh", "Ajit Singh", "Baba Gurdit Singh", "Sohan Singh Bhakna"], answer: 0, explain: "Baba Ram Singh founded it at Bhaini Sahib; it used non-cooperation with British rule.", level: 1 },
      { q: "The Ghadar Party was founded in 1913 at:", options: ["Lahore", "Amritsar", "London", "San Francisco"], answer: 3, explain: "Punjabi immigrants founded the Ghadar Party in San Francisco.", level: 1 },
      { q: "The first president of the Ghadar Party was:", options: ["Sohan Singh Bhakna", "Kartar Singh Sarabha", "Lala Har Dayal", "Bhagat Singh"], answer: 0, explain: "Sohan Singh Bhakna was its president; Lala Har Dayal was among its leaders.", level: 1 },
      { q: "The Jallianwala Bagh massacre took place on:", options: ["13 April 1919", "23 March 1931", "10 February 1846", "1 January 1930"], answer: 0, explain: "On Baisakhi, 13 April 1919, General Dyer ordered firing on an unarmed crowd at Amritsar.", level: 1 },
      { q: "Bhagat Singh, Sukhdev and Rajguru were hanged on:", options: ["13 April 1919", "27 June 1839", "23 March 1931", "15 August 1947"], answer: 2, explain: "They were hanged at Lahore on 23 March 1931.", level: 1 },
      { q: "The SGPC was formed in:", options: ["1873", "1913", "1925", "1920"], answer: 3, explain: "The Shiromani Gurdwara Parbandhak Committee was formed in 1920 to manage gurdwaras.", level: 1 },
      { q: "The Pagri Sambhal Jatta movement of 1907 was a protest by farmers against:", options: ["the Rowlatt Act", "the Colonization Bill and high canal rates", "the Simon Commission", "the Gurdwaras Act"], answer: 1, explain: "Farmers protested the Colonization Bill and heavy canal rates, supported by Lala Lajpat Rai and Ajit Singh.", level: 2 },
      { q: "The ship Komagata Maru was chartered by:", options: ["Baba Gurdit Singh", "Udham Singh", "Dr Satyapal", "Baba Ram Singh"], answer: 0, explain: "Baba Gurdit Singh chartered it in 1914 to take Indians to Canada, but they were refused entry.", level: 2 },
      { q: "The Rowlatt Act (1919) allowed the government to:", options: ["tax farmers heavily", "ban newspapers only", "arrest and imprison people without trial", "distribute canal water"], answer: 2, explain: "Detention without trial caused protests, including in Punjab.", level: 2 },
      { q: "The Akali movement (1920–25) aimed to:", options: ["free gurdwaras from corrupt mahants", "end the Rowlatt Act", "start the Ghadar Party", "form the SGPC only"], answer: 0, explain: "It freed gurdwaras from corrupt mahants and ended with the Sikh Gurdwaras Act, 1925.", level: 2 },
      { q: "Udham Singh shot Michael O'Dwyer in London in:", options: ["1919", "1929", "1940", "1947"], answer: 2, explain: "He killed the former Lieutenant Governor of Punjab in 1940 and was hanged the same year.", level: 2 },
      { q: "The demand for Purna Swaraj was made at the Lahore session of the Congress presided over by:", options: ["Mahatma Gandhi", "Jawaharlal Nehru", "Lala Lajpat Rai", "Bhagat Singh"], answer: 1, explain: "The 1929 Lahore session under Jawaharlal Nehru demanded complete independence.", level: 2 },
      { q: "Assertion (A): The Jallianwala Bagh massacre shocked the whole nation.\nReason (R): Hundreds of unarmed people were killed when General Dyer ordered firing on a peaceful crowd.", options: ["Both A and R are true, and R is the correct explanation of A.", "Both A and R are true, but R is not the correct explanation of A.", "A is true, but R is false.", "A is false, but R is true."], answer: 0, explain: "The killing of an unarmed crowd caused national outrage.", level: 2, keepOrder: true },
      { q: "Assertion (A): The Ghadar movement was a non-violent campaign.\nReason (R): The Ghadar Party called for an armed uprising against the British.", options: ["Both A and R are true, and R is the correct explanation of A.", "Both A and R are true, but R is not the correct explanation of A.", "A is true, but R is false.", "A is false, but R is true."], answer: 3, explain: "The party called for armed revolt, so A is false and R is true.", level: 3, keepOrder: true },
      { q: "Which sequence of events is in the correct chronological order?", options: ["Ghadar Party → Pagri Sambhal Jatta → Jallianwala Bagh", "Pagri Sambhal Jatta → Ghadar Party → Jallianwala Bagh", "Jallianwala Bagh → Ghadar Party → Pagri Sambhal Jatta", "Pagri Sambhal Jatta → Jallianwala Bagh → Ghadar Party"], answer: 1, explain: "Pagri Sambhal Jatta (1907), Ghadar Party (1913), Jallianwala Bagh (1919).", level: 3 },
      { q: "The Gurdwara reform events in correct order are:", options: ["Jaito, Nankana Sahib, Guru ka Bagh", "Nankana Sahib, Guru ka Bagh, Jaito", "Guru ka Bagh, Jaito, SGPC", "Jaito, SGPC, Nankana Sahib"], answer: 1, explain: "SGPC 1920, Nankana Sahib 1921, Guru ka Bagh 1922, Jaito 1923–25.", level: 3 },
      { q: "A protest procession at Lahore against the Simon Commission in 1928 led to the injury and soon the death of:", options: ["Bhagat Singh", "Lala Lajpat Rai", "Sukhdev", "Kartar Singh Sarabha"], answer: 1, explain: "Lala Lajpat Rai was hurt in a lathi charge and died soon after.", level: 3 },
      { q: "Which statement about the 1872 Malerkotla incident is correct?", options: ["Kukas were put to death by the British", "Ghadarites were hanged", "The Akalis won Guru ka Bagh", "Bhagat Singh was arrested"], answer: 0, explain: "In 1872 a number of Kukas were put to death at Malerkotla.", level: 3 }
    ],
    written: [
      { q: "Who founded the Namdhari (Kuka) movement?", a: "Baba Ram Singh, at Bhaini Sahib.", marks: 1 },
      { q: "Who ordered the firing at Jallianwala Bagh?", a: "General Dyer.", marks: 1 },
      { q: "What is meant by Purna Swaraj?", a: "Complete independence from British rule.", marks: 1 },
      { q: "What was the Komagata Maru incident?", a: "In 1914 the ship Komagata Maru carried Indian passengers to Canada but they were refused entry.\nOn return at Budge Budge near Calcutta there was a clash with police in which several lives were lost.", marks: 2 },
      { q: "Name the Singh Sabha and Arya Samaj movements and their aims.", a: "The Singh Sabha (1873, Amritsar) reformed the Sikh community and spread education.\nThe Arya Samaj (Lahore, 1877) worked for social reform and education.", marks: 2 },
      { q: "Who was Kartar Singh Sarabha?", a: "He was a young Ghadar leader.\nHe was executed in 1915 for the Ghadar conspiracy.", marks: 2 },
      { q: "Describe the Pagri Sambhal Jatta movement.", a: "1. It was a 1907 agitation by Punjab farmers.\n2. It was supported by Lala Lajpat Rai and Ajit Singh.\n3. It protested against the Colonization Bill and high canal rates.", marks: 3 },
      { q: "Explain the Ghadar movement.", a: "1. The Ghadar Party was founded in 1913 at San Francisco by Punjabi immigrants.\n2. Sohan Singh Bhakna was president; Lala Har Dayal was among its leaders.\n3. It called for an armed uprising against the British, and Kartar Singh Sarabha was executed in 1915.", marks: 3 },
      { q: "Write a note on the contribution of Bhagat Singh.", a: "1. He was a revolutionary who threw a bomb in the Central Assembly in 1929 in protest.\n2. He was tried in the Saunders case, linked to the death of Lala Lajpat Rai.\n3. He was hanged with Sukhdev and Rajguru at Lahore on 23 March 1931.", marks: 3 },
      { q: "Describe the Jallianwala Bagh massacre and its background.", a: "1. The Rowlatt Act of 1919 allowed detention without trial.\n2. Punjab leaders Dr Saifuddin Kitchlew and Dr Satyapal were arrested and protests grew.\n3. On 13 April 1919 (Baisakhi), a large unarmed crowd gathered at Jallianwala Bagh, Amritsar.\n4. General Dyer ordered troops to fire and hundreds were killed.\n5. The massacre shocked the nation and strengthened the freedom struggle.", marks: 5, type: "long" },
      { q: "Write a note on the Gurdwara Reform (Akali) movement.", a: "1. It aimed to free gurdwaras from corrupt mahants (1920–25).\n2. The SGPC was formed in 1920.\n3. The Nankana Sahib massacre occurred in 1921.\n4. Guru ka Bagh morcha (1922) and Jaito morcha (1923–25) followed.\n5. The movement ended with the Sikh Gurdwaras Act, 1925.", marks: 5, type: "long" },
      { q: "Case study: A young revolutionary from Punjab went to London in 1940 and shot a former Lieutenant Governor of Punjab, recalling the events in Amritsar twenty-one years earlier. He was hanged the same year.\n(i) Name the revolutionary. (ii) Whom did he shoot? (iii) Which event of 1919 was he avenging?", a: "(i) Udham Singh.\n(ii) Michael O'Dwyer.\n(iii) The Jallianwala Bagh massacre.", marks: 4, type: "case" }
    ]
  },
  "democracy-working-functioning": {
    mcq: [
      { q: "The word 'democracy' comes from the Greek words demos and kratos, meaning:", options: ["king and rule", "people and rule", "law and order", "freedom and equality"], answer: 1, explain: "Demos means people and kratos means rule.", level: 1 },
      { q: "A democracy in which people elect representatives to make laws is called:", options: ["direct democracy", "dictatorship", "monarchy", "indirect (representative) democracy"], answer: 3, explain: "India follows representative democracy because direct democracy is practical only in small communities.", level: 1 },
      { q: "The voting age in India is:", options: ["18 years", "21 years", "25 years", "16 years"], answer: 0, explain: "Every citizen aged 18 or above can vote.", level: 1 },
      { q: "Elections in India are conducted by:", options: ["the Supreme Court", "the Parliament", "the Prime Minister", "the Election Commission of India"], answer: 3, explain: "The Election Commission is an independent body that conducts elections.", level: 1 },
      { q: "'Government of the people, by the people, for the people' is a description of democracy given by:", options: ["Abraham Lincoln", "B. R. Ambedkar", "Mahatma Gandhi", "Aristotle"], answer: 0, explain: "Abraham Lincoln described democracy in these words.", level: 1 },
      { q: "'One person, one vote, one value' describes:", options: ["rule of law", "universal adult franchise", "separation of powers", "federalism"], answer: 1, explain: "Universal adult franchise gives every adult citizen an equal vote.", level: 1 },
      { q: "Which of these is a feature of a democratic government?", options: ["Rulers cannot be changed", "Rulers are chosen in free and fair elections", "The army decides all laws", "Citizens have no rights"], answer: 1, explain: "Democratic rulers are elected and can be voted out.", level: 2 },
      { q: "Under the rule of law:", options: ["only citizens are bound by law", "rulers are above the courts", "courts have no role", "everyone, including rulers, is subject to the law"], answer: 3, explain: "No one, however powerful, is above the law.", level: 2 },
      { q: "Separation of powers in India means that:", options: ["only courts make laws", "the Parliament, executive and judiciary have defined roles", "only the army governs", "a king rules"], answer: 1, explain: "Each organ has its own functions and checks the others.", level: 2 },
      { q: "Which of the following is a challenge to democracy in India?", options: ["Free and fair elections", "Universal franchise", "Illiteracy, poverty and corruption", "An independent judiciary"], answer: 2, explain: "Illiteracy, poverty, corruption, casteism, communalism and criminalisation of politics weaken democracy.", level: 2 },
      { q: "Direct democracy is practical only in:", options: ["large countries", "small communities", "federal states", "countries with kings"], answer: 1, explain: "In large societies people cannot decide every issue directly.", level: 2 },
      { q: "In a village meeting, Meena and a farmer's son vote on building a school, and each vote counts equally. This reflects:", options: ["monarchy", "military rule", "dictatorship", "political equality"], answer: 3, explain: "Equal votes for all show political equality.", level: 2 },
      { q: "Assertion (A): In a democracy the government is accountable to the people.\nReason (R): Rulers are elected and can be voted out.", options: ["Both A and R are true, and R is the correct explanation of A.", "Both A and R are true, but R is not the correct explanation of A.", "A is true, but R is false.", "A is false, but R is true."], answer: 0, explain: "Because voters can remove rulers, rulers must answer to them.", level: 2, keepOrder: true },
      { q: "Assertion (A): Direct democracy is the main form of democracy in India.\nReason (R): People elect representatives who make laws and run the government.", options: ["Both A and R are true, and R is the correct explanation of A.", "Both A and R are true, but R is not the correct explanation of A.", "A is true, but R is false.", "A is false, but R is true."], answer: 3, explain: "India is a representative democracy, so A is false; R describes it correctly.", level: 3, keepOrder: true },
      { q: "A candidate promises ward residents better roads, but after winning he ignores them. In the next election the voters defeat him. Which feature of democracy does this show?", options: ["Rulers can be voted out", "Elections are not needed", "Judges elect rulers", "Dictatorship"], answer: 0, explain: "Voters in a democracy can remove rulers who do not perform.", level: 3 },
      { q: "An organisation prevents poor people from voting. Which feature of democracy is violated most directly?", options: ["Separation of powers", "Universal adult franchise", "Federalism", "Judicial review"], answer: 1, explain: "Every adult citizen is entitled to vote, regardless of wealth or status.", level: 3 },
      { q: "Which statement about merits of democracy is correct?", options: ["It is quicker than any other system always", "It allows mistakes to be corrected and resolves conflicts peacefully", "It never faces challenges", "It removes all inequality"], answer: 1, explain: "Democracy improves decisions, respects dignity and allows correction of mistakes, though it has challenges.", level: 3 },
      { q: "Which of the following does NOT strengthen democracy?", options: ["Voting wisely", "Staying informed", "Ignoring public affairs", "Joining public debate"], answer: 2, explain: "Citizens strengthen democracy by voting, staying informed and taking part in public affairs.", level: 3 }
    ],
    written: [
      { q: "What is meant by democracy?", a: "Democracy is a form of government in which the rulers are chosen by the people.", marks: 1 },
      { q: "Name the two types of democracy.", a: "Direct democracy and indirect (representative) democracy.", marks: 1 },
      { q: "Which body conducts elections in India?", a: "The Election Commission of India.", marks: 1 },
      { q: "What is universal adult franchise?", a: "It is the right of every adult citizen to vote without discrimination.\nIt means one person, one vote, one value.", marks: 2 },
      { q: "Distinguish between direct and indirect democracy.", a: "In direct democracy people take decisions themselves; it is practical only in small communities.\nIn indirect democracy people elect representatives who make laws and run the government, as in India.", marks: 2 },
      { q: "What is meant by the rule of law?", a: "Everyone, including rulers, is subject to the law.\nIt is supported by an independent judiciary.", marks: 2 },
      { q: "State three features of democracy.", a: "1. Rulers are elected in free and fair elections and can be voted out.\n2. Universal adult franchise: one person, one vote, one value.\n3. Citizens enjoy basic rights and the rule of law.", marks: 3 },
      { q: "State three merits of democracy.", a: "1. It promotes equality and respects human dignity.\n2. It improves the quality of decisions.\n3. It resolves conflicts peacefully and allows mistakes to be corrected.", marks: 3 },
      { q: "How can citizens strengthen democracy in India?", a: "1. By voting in elections.\n2. By staying informed.\n3. By taking part in public affairs and debate.", marks: 3 },
      { q: "Explain the challenges faced by democracy in India.", a: "1. Illiteracy and poverty reduce informed participation.\n2. Corruption weakens trust in institutions.\n3. Casteism and communalism divide society.\n4. Criminalisation of politics and money power distort elections.\n5. Low participation of citizens weakens accountability.", marks: 5, type: "long" },
      { q: "Describe how democracy functions in India.", a: "1. India is a democratic republic with a Constitution guaranteeing Fundamental Rights.\n2. It follows a parliamentary system with separate roles for Parliament, executive and judiciary.\n3. Elections are conducted by the independent Election Commission.\n4. Every citizen aged 18 or above can vote.\n5. The government is accountable to the people and the rule of law applies to all.", marks: 5, type: "long" },
      { q: "Case study: In a town every adult resident, whatever their caste or income, votes to choose a representative. The government decides after discussion, and citizens can question their representative.\n(i) Which type of democracy is this? (ii) Name the feature shown by equal voting rights. (iii) Which feature is shown by citizens questioning the representative?", a: "(i) Indirect (representative) democracy.\n(ii) Universal adult franchise.\n(iii) Accountability of the government to the people.", marks: 4, type: "case" }
    ]
  },
  "power-sharing-in-democracy": {
    mcq: [
      { q: "In Belgium, the largest share of the population speaks:", options: ["French", "Dutch", "German", "English"], answer: 1, explain: "About 59 per cent speak Dutch, 40 per cent French and 1 per cent German.", level: 1 },
      { q: "In Sri Lanka, the majority community is:", options: ["Tamil", "Sinhala", "Muslim", "Burgher"], answer: 1, explain: "About 74 per cent of Sri Lankans are Sinhala and about 18 per cent Tamil.", level: 1 },
      { q: "Sri Lanka became independent in:", options: ["1948", "1956", "1947", "2009"], answer: 0, explain: "Sri Lanka gained independence in 1948.", level: 1 },
      { q: "The 1956 Act in Sri Lanka made which language the only official language?", options: ["Tamil", "English", "Sinhala", "Hindi"], answer: 2, explain: "The Act recognised Sinhala as the only official language, causing Tamil resentment.", level: 1 },
      { q: "Sharing power among the legislature, executive and judiciary is called:", options: ["vertical power sharing", "horizontal power sharing", "community government", "coalition"], answer: 1, explain: "Horizontal power sharing divides power among organs of government at the same level.", level: 1 },
      { q: "A government formed by two or more parties together is called a:", options: ["coalition government", "community government", "federal government", "military government"], answer: 0, explain: "Coalition governments share power among parties.", level: 1 },
      { q: "The belief that the majority community should rule as it likes, ignoring minorities, is called:", options: ["federalism", "majoritarianism", "secularism", "pluralism"], answer: 1, explain: "Majoritarianism harms national unity in the long run.", level: 2 },
      { q: "A prudential reason for power sharing is that it:", options: ["is the spirit of democracy", "reduces conflict and keeps the country stable", "gives the majority all power", "removes elections"], answer: 1, explain: "Prudential reasons relate to benefits like stability and avoiding conflict.", level: 2 },
      { q: "A moral reason for power sharing is that:", options: ["it brings greater profits", "it ends the need for law", "it is the very spirit of democracy and people have a right to be consulted", "it weakens opposition"], answer: 2, explain: "Moral reasons value power sharing for its own sake as part of democracy.", level: 2 },
      { q: "Dividing power between the Union government, states and local bodies is:", options: ["horizontal", "vertical", "among social groups", "among parties"], answer: 1, explain: "Vertical power sharing divides power between governments at different levels.", level: 2 },
      { q: "In Belgium, the central government has:", options: ["only French-speaking ministers", "an equal number of Dutch- and French-speaking ministers", "no ministers from Brussels", "only Dutch ministers"], answer: 1, explain: "This equal representation is one of Belgium's power-sharing arrangements.", level: 2 },
      { q: "Reserved seats for women and weaker sections in legislatures is an example of power sharing:", options: ["among organs of government", "between governments", "among social groups", "among movements only"], answer: 2, explain: "Reserving seats shares power among social groups.", level: 2 },
      { q: "Assertion (A): Belgium shared power between Dutch- and French-speaking communities.\nReason (R): Constitutional amendments between 1970 and 1993 created community governments and equal ministers.", options: ["Both A and R are true, and R is the correct explanation of A.", "Both A and R are true, but R is not the correct explanation of A.", "A is true, but R is false.", "A is false, but R is true."], answer: 0, explain: "The amendments created the arrangements by which power is shared.", level: 2, keepOrder: true },
      { q: "Assertion (A): Sri Lanka's Sinhala-only Act helped bring peace.\nReason (R): The Tamils felt discriminated against, leading to demands for autonomy and civil war.", options: ["Both A and R are true, and R is the correct explanation of A.", "Both A and R are true, but R is not the correct explanation of A.", "A is true, but R is false.", "A is false, but R is true."], answer: 3, explain: "The Act caused alienation, not peace; R is true.", level: 3, keepOrder: true },
      { q: "Brussels in Belgium shows power sharing because:", options: ["it has a separate government with equal representation for both communities", "it has only French rulers", "it has no government", "it is ruled by the central government alone"], answer: 0, explain: "Brussels has its own government in which both language communities are represented.", level: 3 },
      { q: "A community government in Belgium deals with:", options: ["defence", "foreign policy", "cultural, educational and language matters", "currency"], answer: 2, explain: "It is elected by one language community and handles its cultural and educational matters.", level: 3 },
      { q: "A state legislature makes laws on subjects assigned to it by the Constitution, while Parliament makes laws on Union subjects. This is an example of:", options: ["horizontal power sharing", "vertical power sharing", "majoritarianism", "a coalition government"], answer: 1, explain: "Federal division of power between the Union and the states is vertical power sharing.", level: 3 },
      { q: "When the judiciary strikes down an unconstitutional law passed by the legislature, it shows:", options: ["checks and balances", "majoritarianism", "coalition", "community government"], answer: 0, explain: "Each organ limits the power of the others.", level: 3 }
    ],
    written: [
      { q: "What is power sharing?", a: "Dividing power among different organs, levels and groups of society.", marks: 1 },
      { q: "When did the civil war in Sri Lanka end?", a: "In 2009.", marks: 1 },
      { q: "What are checks and balances?", a: "A system in which each organ of government limits the power of the others.", marks: 1 },
      { q: "Give the language-wise population of Belgium.", a: "Dutch about 59 per cent, French about 40 per cent and German about 1 per cent.\nIn Brussels about 80 per cent speak French and 20 per cent Dutch.", marks: 2 },
      { q: "Distinguish between prudential and moral reasons for power sharing.", a: "Prudential: it reduces conflict and keeps the country stable and united.\nMoral: it is the spirit of democracy, and people have a right to be consulted.", marks: 2 },
      { q: "Why is majoritarianism harmful?", a: "It ignores the interests of minorities and causes resentment.\nIt harms national unity in the long run.", marks: 2 },
      { q: "Describe the power-sharing arrangements in Belgium.", a: "1. The central government has equal numbers of Dutch- and French-speaking ministers.\n2. State governments are not subordinate to the central government.\n3. Brussels has a separate government and a community government handles cultural and language matters.", marks: 3 },
      { q: "Why did a civil war break out in Sri Lanka?", a: "1. Sinhala majority imposed its will after 1948; the 1956 Act made Sinhala the only official language.\n2. Tamils felt discriminated against in jobs and education.\n3. Their demands for autonomy grew and led to a civil war.", marks: 3 },
      { q: "State three forms of power sharing.", a: "1. Horizontal: among legislature, executive and judiciary.\n2. Vertical: among Union, state and local governments.\n3. Among social groups, and among parties, pressure groups and movements.", marks: 3 },
      { q: "Explain why power sharing is desirable.", a: "1. Prudential reason: it reduces conflict between groups.\n2. It keeps the country stable and united.\n3. Moral reason: it is the spirit of democracy.\n4. People have a right to be consulted about how they are governed.\n5. Majoritarianism may look attractive but harms unity in the long run.", marks: 5, type: "long" },
      { q: "Compare the cases of Belgium and Sri Lanka.", a: "1. Belgium's majority speaks Dutch (59%); Sri Lanka's majority is Sinhala (74%).\n2. Belgium recognised the interests of all communities and shared power through amendments between 1970 and 1993.\n3. Sri Lanka's majority imposed its will, e.g. the 1956 Act.\n4. Belgium achieved stability through equal ministers and community governments.\n5. Sri Lanka's discrimination led to demands for autonomy and a civil war ending in 2009.", marks: 5, type: "long" },
      { q: "Case study: In a country, the majority community passes a law making its language the only official one, and refuses to share jobs with the minority. The minority begins to demand autonomy.\n(i) Which country's example does this resemble? (ii) What is this attitude of the majority called? (iii) Suggest one way to resolve the conflict.", a: "(i) Sri Lanka.\n(ii) Majoritarianism.\n(iii) Share power by recognising both languages and giving the minority fair representation, as Belgium did.", marks: 4, type: "case" }
    ]
  },
  "competition-and-contestation-in-democracy": {
    mcq: [
      { q: "A group of people who come together to contest elections and hold power is a:", options: ["pressure group", "political party", "movement", "trade union"], answer: 1, explain: "Political parties contest elections to hold power.", level: 1 },
      { q: "The party system of India is:", options: ["one-party", "two-party", "multi-party", "no-party"], answer: 2, explain: "India has many parties, so it has a multi-party system.", level: 1 },
      { q: "Which country has a one-party system?", options: ["USA", "UK", "India", "China"], answer: 3, explain: "China has a one-party system; the USA and UK have two-party systems.", level: 1 },
      { q: "Parties that do not form the government and criticise it are called the:", options: ["opposition", "coalition", "movement", "regulators"], answer: 0, explain: "The opposition keeps the government in check.", level: 1 },
      { q: "Organisations that influence government policy without contesting elections are:", options: ["political parties", "pressure groups", "election commissions", "regents"], answer: 1, explain: "Pressure groups like trade unions try to influence policy but do not seek power.", level: 1 },
      { q: "The law that prevents elected members from changing parties is the:", options: ["rule of law", "anti-defection law", "right to information law", "franchise law"], answer: 1, explain: "Under the anti-defection law, a legislator who leaves the party loses the seat.", level: 1 },
      { q: "Parties are recognised as national or state parties by:", options: ["the Election Commission", "the Parliament", "the Supreme Court", "the President"], answer: 0, explain: "Recognition depends on the votes and seats won.", level: 2 },
      { q: "The Chipko movement is an example of a:", options: ["political party", "movement for a cause", "coalition government", "pressure group of traders"], answer: 1, explain: "Movements are mass campaigns for a cause.", level: 2 },
      { q: "A pressure group that works for the interests of one section, such as farmers, is:", options: ["promotional", "sectional", "national", "regional party"], answer: 1, explain: "Sectional groups represent the interests of one section; promotional groups promote a public cause.", level: 2 },
      { q: "Why does competition between parties help citizens?", options: ["It ends elections", "It keeps rulers accountable", "It removes opposition", "It reduces voting"], answer: 1, explain: "Parties know they can lose power if they do not perform.", level: 2 },
      { q: "Which is a function of political parties?", options: ["Contesting elections", "Conducting elections", "Deciding court cases", "Printing currency"], answer: 0, explain: "Parties contest elections, form governments or act as opposition.", level: 2 },
      { q: "A group of citizens wants the government to pass a law on the right to information, but its members do not contest elections. This group is a:", options: ["political party", "movement or pressure group", "coalition government", "regional party"], answer: 1, explain: "Campaigns for a public cause without contesting elections are movements or promotional pressure groups.", level: 2 },
      { q: "Assertion (A): Free and fair elections are essential for competition in democracy.\nReason (R): An independent Election Commission supervises elections.", options: ["Both A and R are true, and R is the correct explanation of A.", "Both A and R are true, but R is not the correct explanation of A.", "A is true, but R is false.", "A is false, but R is true."], answer: 0, explain: "Independent supervision helps make elections free and fair.", level: 2, keepOrder: true },
      { q: "Assertion (A): Pressure groups contest elections to form the government.\nReason (R): Pressure groups try to influence policy without seeking power.", options: ["Both A and R are true, and R is the correct explanation of A.", "Both A and R are true, but R is not the correct explanation of A.", "A is true, but R is false.", "A is false, but R is true."], answer: 3, explain: "Pressure groups do not contest elections, so A is false; R is true.", level: 3, keepOrder: true },
      { q: "Which is a problem in party politics?", options: ["Internal democracy within parties", "Dynastic politics and money and muscle power", "Free choice for voters", "Anti-defection law"], answer: 1, explain: "Lack of internal democracy, dynastic politics and money and muscle power are challenges.", level: 3 },
      { q: "The requirement that candidates declare their property and criminal cases through affidavits is meant to:", options: ["help voters make informed choices", "raise taxes", "stop elections", "reduce the number of parties"], answer: 0, explain: "Disclosure is a reform to increase transparency in elections.", level: 3 },
      { q: "Which pair is correctly matched?", options: ["Two-party system – India", "One-party system – USA", "Multi-party system – India", "Multi-party system – China"], answer: 2, explain: "India has many parties; USA and UK two; China one.", level: 3 },
      { q: "A state-level party wins many seats in a coalition and joins the government. Which statement is true?", options: ["It can influence policy as part of the government", "It must give up its recognition", "It cannot be an opposition party", "It becomes a pressure group"], answer: 0, explain: "Parties in a coalition share government power.", level: 3 }
    ],
    written: [
      { q: "What is a political party?", a: "A political party is a group of people who contest elections and aim to hold power.", marks: 1 },
      { q: "What is an opposition party?", a: "A party that does not form the government and criticises it.", marks: 1 },
      { q: "Give one example of a movement in India.", a: "The Chipko movement (or the movement for the right to information).", marks: 1 },
      { q: "State any two functions of political parties.", a: "They contest elections and put forward policies.\nThey form and run governments or act as opposition.", marks: 2 },
      { q: "Distinguish between a pressure group and a political party.", a: "A political party contests elections to hold power.\nA pressure group influences government policy without contesting elections.", marks: 2 },
      { q: "What is the anti-defection law?", a: "A law under which a legislator who leaves the party loses the seat.\nIt prevents elected members from switching parties.", marks: 2 },
      { q: "Explain how competition helps democracy.", a: "1. Parties compete for votes, so rulers must perform to win again.\n2. Voters can choose between candidates and parties.\n3. Rulers are accountable because they can lose power.", marks: 3 },
      { q: "Describe the party systems of the world.", a: "1. One-party system, as in China.\n2. Two-party system, as in USA and UK.\n3. Multi-party system, as in India.", marks: 3 },
      { q: "Distinguish between sectional and promotional pressure groups.", a: "1. Sectional groups represent the interests of one group, e.g. trade unions or farmers.\n2. Promotional groups promote a public cause for the good of all.\n3. Both enlarge participation and make governments responsive.", marks: 3 },
      { q: "Explain the challenges faced by political parties and suggest reforms.", a: "1. Lack of internal democracy in parties.\n2. Dynastic politics.\n3. Money and muscle power in elections and limited choice.\n4. Reforms: anti-defection law and affidavits on property and criminal cases.\n5. Citizens can help by voting wisely and joining public debate.", marks: 5, type: "long" },
      { q: "Describe the functions of political parties in a democracy.", a: "1. They contest elections.\n2. They put forward policies and programmes.\n3. They make laws and form and run governments.\n4. They act as opposition when out of power.\n5. They shape public opinion and give access to government schemes.", marks: 5, type: "long" },
      { q: "Case study: Farmers in a state form an association that meets ministers and holds peaceful rallies to demand better prices, but it does not field any candidate in elections.\n(i) What type of organisation is this? (ii) Is it a sectional or promotional group? (iii) How does it differ from a party?", a: "(i) A pressure group.\n(ii) Sectional, since it represents the interests of one group.\n(iii) It does not contest elections or seek power, while a party does.", marks: 4, type: "case" }
    ]
  },
  "outcomes-of-democracy-pseb": {
    mcq: [
      { q: "A government that people can choose and remove is called:", options: ["accountable", "legitimate only", "transparent only", "arbitrary"], answer: 0, explain: "Accountability means rulers answer to the people.", level: 1 },
      { q: "A government accepted by the people as rightful is:", options: ["responsive", "legitimate", "accountable only", "colonial"], answer: 1, explain: "Legitimacy means people accept the government as their own.", level: 1 },
      { q: "A government that considers the needs of the people is:", options: ["transparent", "legitimate", "responsive", "arbitrary"], answer: 2, explain: "A responsive government pays attention to people's needs.", level: 1 },
      { q: "Rule by one person or group without the people's consent is:", options: ["democracy", "dictatorship", "federation", "coalition"], answer: 1, explain: "A dictatorship has no consent of the people.", level: 1 },
      { q: "Which tool helps secure transparency in democracy?", options: ["Right to information", "Censorship", "Secret decisions", "Army orders"], answer: 0, explain: "Elections, public debate and the right to information keep decisions open to scrutiny.", level: 1 },
      { q: "Equal voting rights for every citizen is called:", options: ["economic equality", "political equality", "social inequality", "dictatorship"], answer: 1, explain: "Political equality gives each citizen one vote of equal value.", level: 1 },
      { q: "Democracy is considered better than dictatorship mainly because it:", options: ["always grows faster", "promotes equality, dignity and peaceful resolution of conflicts", "has no rules", "needs no elections"], answer: 1, explain: "Growth rates are not guaranteed to be higher; its strengths lie in equality, dignity and accommodation.", level: 2 },
      { q: "On economic growth, democracy:", options: ["guarantees faster growth", "cannot grow at all", "does not guarantee faster growth but the difference from dictatorships is small", "grows slower in all cases"], answer: 2, explain: "The notes say the difference in growth between democracies and dictatorships is small.", level: 2 },
      { q: "The weakest part of democracy's performance is:", options: ["legitimacy", "dignity", "economic inequality", "accommodation of diversity"], answer: 2, explain: "Political equality exists but economic inequality and poverty remain serious challenges.", level: 2 },
      { q: "Decisions in a democracy may take longer because:", options: ["of discussion and consultation, but they are more acceptable", "rulers are lazy", "courts delay all work", "citizens avoid voting"], answer: 0, explain: "Consultation takes time but gives decisions greater acceptance.", level: 2 },
      { q: "People complaining about the government shows that:", options: ["democracy has failed", "they have become citizens rather than subjects", "elections are unnecessary", "they are dictators"], answer: 1, explain: "Complaints show that people question their rulers, a sign of democratic awareness.", level: 2 },
      { q: "A woman from a disadvantaged caste votes and contests a local election. This enhances democracy's outcome of:", options: ["dignity and freedom of citizens", "faster growth only", "military power", "dictatorship"], answer: 0, explain: "Democracy enhances dignity and freedom, including that of women and disadvantaged castes.", level: 2 },
      { q: "Assertion (A): A democratic government is legitimate.\nReason (R): People accept it as their own and have chosen it.", options: ["Both A and R are true, and R is the correct explanation of A.", "Both A and R are true, but R is not the correct explanation of A.", "A is true, but R is false.", "A is false, but R is true."], answer: 0, explain: "Acceptance by the people makes it legitimate.", level: 2, keepOrder: true },
      { q: "Assertion (A): Democracy guarantees that economic inequality will disappear.\nReason (R): Democracies are based on political equality, but economic inequality remains.", options: ["Both A and R are true, and R is the correct explanation of A.", "Both A and R are true, but R is not the correct explanation of A.", "A is true, but R is false.", "A is false, but R is true."], answer: 3, explain: "Economic inequality persists in democracies, so A is false while R is true.", level: 3, keepOrder: true },
      { q: "Belgium is used as an example to show that democracy:", options: ["ends diversity", "accommodates social diversity through peaceful procedures", "needs a single language", "avoids elections"], answer: 1, explain: "Belgium shared power among language communities.", level: 3 },
      { q: "Which statement is correct?", options: ["Democracy automatically produces good outcomes whatever citizens do", "Democracy creates the conditions for good outcomes but citizens must use them", "Dictatorships are always more legitimate", "Elections are only for show"], answer: 1, explain: "Democracy is a form of government; its results depend on citizens' participation.", level: 3 },
      { q: "A citizen files a request to see how funds for a village road were spent. Which democratic quality is she using?", options: ["Transparency through the right to information", "Dictatorship", "Majoritarianism", "Coalition"], answer: 0, explain: "The right to information lets citizens examine decisions and procedures.", level: 3 },
      { q: "A council ignores a petition signed by hundreds of residents about contaminated water. Which quality is missing?", options: ["Responsiveness", "Legitimacy of elections", "Political equality in voting", "Rule by law"], answer: 0, explain: "A responsive government considers people's needs.", level: 3 }
    ],
    written: [
      { q: "What is meant by an accountable government?", a: "A government that is answerable to the people, who can choose and remove it.", marks: 1 },
      { q: "What is meant by a legitimate government?", a: "A government accepted by the people as rightful.", marks: 1 },
      { q: "What does transparency mean?", a: "Citizens' ability to examine decisions and procedures.", marks: 1 },
      { q: "State two reasons why democracy is a better form of government.", a: "It promotes equality and the dignity of citizens.\nIt improves the quality of decisions and allows mistakes to be corrected.", marks: 2 },
      { q: "Name two tools of transparency in democracy.", a: "Elections and public debate.\nThe right to information.", marks: 2 },
      { q: "Why are people's complaints a sign of democracy's success?", a: "They show people have become citizens rather than subjects.\nThey feel free to question and hold rulers accountable.", marks: 2 },
      { q: "Explain the three qualities of a democratic government.", a: "1. Accountable: people can choose and remove rulers.\n2. Responsive: it considers people's needs.\n3. Legitimate: it is accepted by the people as their own.", marks: 3 },
      { q: "How does democracy handle social diversity?", a: "1. It provides peaceful procedures for competition among groups.\n2. Belgium is an example of sharing power among communities.\n3. It accommodates diversity instead of suppressing it.", marks: 3 },
      { q: "Does democracy ensure economic growth and equality? Explain.", a: "1. Democracy does not guarantee faster economic growth.\n2. The difference between democracies and dictatorships in growth is small.\n3. Political equality exists but economic inequality and poverty remain serious challenges.", marks: 3 },
      { q: "Discuss the outcomes of democracy.", a: "1. It makes government accountable, responsive and legitimate.\n2. Decisions are taken after discussion and are more acceptable.\n3. Transparency is secured by elections, public debate and the right to information.\n4. It accommodates diversity and enhances the dignity and freedom of citizens.\n5. Its weakest area is economic inequality; growth is not guaranteed to be faster.", marks: 5, type: "long" },
      { q: "Why do people prefer democracy even though it may not deliver everything?", a: "1. It promotes equality and respects dignity.\n2. It improves decisions through consultation.\n3. It resolves conflicts peacefully.\n4. Mistakes can be corrected through elections.\n5. It is the people's own government, so it is legitimate.", marks: 5, type: "long" },
      { q: "Case study: In a village the panchayat holds an open meeting every month, publishes its accounts, and a resident uses an application to ask about the money spent on a well.\n(i) Which democratic quality is shown by publishing accounts? (ii) Which right did the resident use? (iii) Name one more feature of accountable government.", a: "(i) Transparency.\n(ii) The right to information.\n(iii) People can choose and remove rulers (elections), or rulers must answer to the people.", marks: 4, type: "case" }
    ]
  },
  "international-democratic-institutions-india": {
    mcq: [
      { q: "The United Nations was founded on:", options: ["24 October 1945", "10 December 1948", "15 August 1947", "26 January 1950"], answer: 0, explain: "The UN was founded on 24 October 1945 after the Second World War.", level: 1 },
      { q: "The headquarters of the United Nations are in:", options: ["Geneva", "London", "Paris", "New York"], answer: 3, explain: "UN headquarters are in New York.", level: 1 },
      { q: "The International Court of Justice is located at:", options: ["The Hague", "New York", "Geneva", "Vienna"], answer: 0, explain: "The ICJ at The Hague settles disputes between states.", level: 1 },
      { q: "The number of permanent members in the UN Security Council is:", options: ["10", "15", "5", "51"], answer: 2, explain: "The five permanent members are the USA, UK, France, Russia and China; there are also 10 non-permanent members.", level: 1 },
      { q: "The Universal Declaration of Human Rights was adopted in:", options: ["1945", "1948", "1950", "1985"], answer: 1, explain: "The UDHR was adopted on 10 December 1948.", level: 1 },
      { q: "Which agency of the UN deals with health?", options: ["UNESCO", "FAO", "ILO", "WHO"], answer: 3, explain: "WHO deals with health; UNESCO with education, science and culture; FAO with food and agriculture.", level: 1 },
      { q: "The power of a permanent member of the Security Council to block a resolution is called:", options: ["veto", "mandate", "franchise", "regency"], answer: 0, explain: "A single veto can block a Security Council resolution.", level: 2 },
      { q: "Non-permanent members of the Security Council are elected for:", options: ["one year", "two years", "five years", "life"], answer: 1, explain: "Ten non-permanent members are elected for two years.", level: 2 },
      { q: "UNESCO works in the field of:", options: ["labour", "children's welfare", "education, science and culture", "health"], answer: 2, explain: "UNESCO stands for education, science and culture.", level: 2 },
      { q: "In the General Assembly, each member country has:", options: ["one vote", "votes in proportion to population", "a veto", "no vote"], answer: 0, explain: "All members have one vote each in the General Assembly.", level: 2 },
      { q: "India's role in UN peacekeeping includes sending:", options: ["no troops", "troops and the first all-women police unit to Liberia (2007)", "only money", "only doctors"], answer: 1, explain: "India is among the largest troop contributors and sent an all-women police unit to Liberia in 2007.", level: 2 },
      { q: "Vijaya Lakshmi Pandit became the first woman:", options: ["Secretary-General of the UN", "Judge of the ICJ", "President of the UN General Assembly", "Permanent member of the Security Council"], answer: 2, explain: "She was President of the UN General Assembly in 1953.", level: 2 },
      { q: "Assertion (A): India is a founding member of the United Nations.\nReason (R): India was among the original members when the UN began in 1945.", options: ["Both A and R are true, and R is the correct explanation of A.", "Both A and R are true, but R is not the correct explanation of A.", "A is true, but R is false.", "A is false, but R is true."], answer: 0, explain: "India was an original member in 1945.", level: 2, keepOrder: true },
      { q: "Assertion (A): India has a permanent seat with veto power in the Security Council.\nReason (R): India has been elected several times as a non-permanent member and demands UN reforms.", options: ["Both A and R are true, and R is the correct explanation of A.", "Both A and R are true, but R is not the correct explanation of A.", "A is true, but R is false.", "A is false, but R is true."], answer: 3, explain: "India does not have a permanent seat, so A is false; R is true.", level: 3, keepOrder: true },
      { q: "Two countries have a dispute over a river boundary and want a legal decision. Which UN organ would they approach?", options: ["General Assembly", "Secretariat", "International Court of Justice", "Trusteeship Council"], answer: 2, explain: "The ICJ settles legal disputes between states.", level: 3 },
      { q: "A resolution is supported by 14 of the 15 Security Council members but one permanent member votes against it. The result is:", options: ["the resolution passes", "the resolution is blocked by the veto", "the General Assembly decides", "the vote is repeated"], answer: 1, explain: "A negative vote by any permanent member can block a resolution.", level: 3 },
      { q: "Which pair is correctly matched?", options: ["UNICEF – children's welfare", "FAO – health", "ILO – education", "WHO – agriculture"], answer: 0, explain: "UNICEF works for children's welfare; FAO deals with food and agriculture, ILO with labour and WHO with health.", level: 3 },
      { q: "Which organisation was founded in 1985 with India's leading role in the region?", options: ["UN", "SAARC", "ICJ", "UNESCO"], answer: 1, explain: "SAARC, formed in 1985, is a regional grouping of South Asian countries; India also played a leading role in the Non-Aligned Movement.", level: 3 }
    ],
    written: [
      { q: "When was the United Nations founded?", a: "On 24 October 1945.", marks: 1 },
      { q: "Name the permanent members of the UN Security Council.", a: "USA, UK, France, Russia and China.", marks: 1 },
      { q: "What is the ICJ?", a: "The International Court of Justice, the UN's main judicial organ, at The Hague.", marks: 1 },
      { q: "What is meant by veto?", a: "The power of a permanent member of the Security Council to block a resolution.\nA single permanent member's negative vote is enough.", marks: 2 },
      { q: "Name two specialised agencies of the UN and their work.", a: "WHO – health.\nUNESCO – education, science and culture (or FAO, ILO, UNICEF).", marks: 2 },
      { q: "State two contributions of India to the work of the UN.", a: "India is a founding member and a major contributor of troops to UN peacekeeping.\nIn 2007 it sent the first all-women police unit to Liberia.", marks: 2 },
      { q: "Explain the objectives of the United Nations.", a: "1. To maintain international peace and security.\n2. To promote cooperation among nations.\n3. To promote human rights, as in the UDHR (1948).", marks: 3 },
      { q: "Describe the composition of the Security Council.", a: "1. It is responsible for peace and security.\n2. It has 5 permanent members with veto power: USA, UK, France, Russia and China.\n3. It has 10 non-permanent members elected for two years.", marks: 3 },
      { q: "Describe the role of the General Assembly and the Secretariat.", a: "1. The General Assembly has all members, each with one vote, and discusses world issues.\n2. The Secretariat is headed by the Secretary-General.\n3. It carries out the day-to-day administration of the UN.", marks: 3 },
      { q: "Describe the main organs of the United Nations.", a: "1. General Assembly: all members, one vote each.\n2. Security Council: peace and security with 5 permanent and 10 non-permanent members.\n3. ECOSOC: economic and social cooperation.\n4. ICJ at The Hague settles disputes between states.\n5. Secretariat under the Secretary-General; the Trusteeship Council has suspended operations since 1994.", marks: 5, type: "long" },
      { q: "Discuss India's role in international institutions.", a: "1. India is a founding member of the UN (1945).\n2. It is one of the largest contributors of troops to UN peacekeeping.\n3. In 2007 it sent the first all-women police unit to Liberia.\n4. Vijaya Lakshmi Pandit was the first woman President of the General Assembly (1953).\n5. India has served as a non-permanent member, demands UN reforms and a permanent seat, and played a leading role in NAM and SAARC (1985).", marks: 5, type: "long" },
      { q: "Case study: A country asks for peacekeeping troops to maintain peace after a conflict. Soldiers from several nations, including India, arrive under a UN flag. Health workers from a UN agency set up clinics.\n(i) What is this activity of the UN called? (ii) Which agency deals with health? (iii) Which Security Council feature can block a resolution to send troops?", a: "(i) Peacekeeping.\n(ii) WHO.\n(iii) The veto power of a permanent member.", marks: 4, type: "case" }
    ]
  }
});
